{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "male",
        "extension": [
          {
            "url": "https://example.org/fhir/StructureDefinition/indigenous-status",
            "valueString": "Aboriginal"
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Acute-on-chronic mechanical low back pain, likely muscular/degenerative strain on background osteoarthritis-type changes"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Longstanding intermittent mechanical low back pain; current flare worsened over the last 5–6 days. Muscular/degenerative cause is considered likely. No red flags identified on history or limited telehealth assessment."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Suspected chronic kidney disease stage 3"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "note": [
          {
            "text": "CKD stage 3 is questioned in the history; last known eGFR approximately 45 at discharge."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Possible recurrent hyperkalaemia"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        },
        "note": [
          {
            "text": "Known prior severe hyperkalaemia with potassium peak 6.3 during admission approximately 3 months ago. Patient reports being told potassium was elevated again approximately 10 days ago, with no values available. Assessment identifies recurrent hyperkalaemia risk in the setting of CKD, ACE inhibitor use and increased potassium intake. Current pathology results have not been received."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Type 2 diabetes mellitus with suboptimal control by history"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Prior HHS approximately 3 months ago; no current HHS features identified."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-5",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-5",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Prior hyperosmolar hyperglycaemic state"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "resolved"
            }
          ]
        },
        "note": [
          {
            "text": "HHS admission approximately 3 months ago; now on a simplified oral diabetes regimen."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-6",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-6",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Hypertension"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-7",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-7",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Hyperlipidaemia"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Reported low back pain characteristics"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Longstanding chronic intermittent dull central low back ache, possibly extending into both buttocks, without clear leg radiation. Worsened over the last 5–6 days after helping grandchildren with wood; patient thinks he may have twisted incorrectly. Worse with bending and twisting and in the evenings; eased by curling up. More stiff in the morning."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Reported low back pain severity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Baseline pain score out of 10"
            },
            "valueQuantity": {
              "value": 5,
              "comparator": null
            }
          },
          {
            "code": {
              "text": "Pain score with bending or twisting out of 10"
            },
            "valueQuantity": {
              "value": 7
            }
          }
        ],
        "note": [
          {
            "text": "Baseline pain approximately 5/10, increasing up to 7/10 with bending or twisting."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Low back pain red-flag and associated history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies trauma or fall, saddle anaesthesia, leg weakness, foot drop, bladder or bowel incontinence, fever, night sweats, weight loss, recent infection, intravenous drug use and cancer history. No spinal surgery reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Reported mobility"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mobilises short distances at home; uses a single-point stick outdoors."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Historical peak potassium"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 6.3
        },
        "note": [
          {
            "text": "Peak during the admission approximately 3 months ago; units not stated. Settled with insulin, dextrose and fluids; ACE inhibitor was held according to the discharge summary."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Historical estimated glomerular filtration rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 45
        },
        "note": [
          {
            "text": "Approximately 45 at discharge; units not stated."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Reported recent potassium result"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports the local clinic nurse checked sugars and salts approximately 10 days ago and said potassium was a bit elevated again. No numeric result available."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Current reported general, cardiac and neuromuscular symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Feels a bit sluggish. Denies palpitations, chest pain, presyncope, frank muscle weakness and shortness of breath; describes 'just old man weakness'."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Reported dietary intake relevant to potassium"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Increased fresh fruit intake since admission, including bananas most mornings. Uses a 'low salt' substitute from town, considered likely potassium chloride based. Limited access to fresh food and increased tinned/processed foods."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported blood glucose readings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Usual reported blood glucose range"
            },
            "valueRange": {
              "low": {
                "value": 14
              },
              "high": {
                "value": 15
              }
            }
          },
          {
            "code": {
              "text": "Occasional reported blood glucose range"
            },
            "valueRange": {
              "low": {
                "value": 8
              },
              "high": {
                "value": 9
              }
            }
          }
        ],
        "note": [
          {
            "text": "Checked by community nurse 2–3 times weekly. Units not stated. Patient has no own glucometer."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Current diabetes-related symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies polyuria, polydipsia, confusion and visual blurring."
      }
    },
